package com.fasterxml.jackson.core.io;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumberInput_parseBigDecimal_TriageGen2Test {

    @Test
    public void testParseBigDecimal_ValidInteger() {
        char[] buffer = "12345".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 5);
        assertEquals(new BigDecimal("12345"), result);
    }

    @Test
    public void testParseBigDecimal_ValidDecimal() {
        char[] buffer = "123.456".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 7);
        assertEquals(new BigDecimal("123.456"), result);
    }

    @Test
    public void testParseBigDecimal_WithOffsetAndLen() {
        // Buffer: "abc123def" -> we want "123"
        char[] buffer = "abc123def".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 3, 3);
        assertEquals(new BigDecimal("123"), result);
    }

    @Test
    public void testParseBigDecimal_Negative() {
        char[] buffer = "-123.45".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 7);
        assertEquals(new BigDecimal("-123.45"), result);
    }

    @Test
    public void testParseBigDecimal_ScientificNotation() {
        char[] buffer = "1.23E10".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 7);
        assertEquals(new BigDecimal("1.23E10"), result);
    }

    @Test
    public void testParseBigDecimal_Zero() {
        char[] buffer = "0".toCharArray();
        BigDecimal result = NumberInput.parseBigDecimal(buffer, 0, 1);
        assertEquals(BigDecimal.ZERO, result);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_InvalidCharacters() {
        char[] buffer = "12a34".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 5);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_EmptyRange() {
        char[] buffer = "123".toCharArray();
        // len 0 might throw exception depending on BigDecimal implementation, 
        // but usually, an empty string is not a valid number.
        NumberInput.parseBigDecimal(buffer, 0, 0);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testParseBigDecimal_OffsetOutOfBounds() {
        char[] buffer = "123".toCharArray();
        NumberInput.parseBigDecimal(buffer, 5, 1);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_MultipleDecimals() {
        char[] buffer = "1.2.3".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 5);
    }

    @Test(expected = NumberFormatException.class)
    public void testParseBigDecimal_OnlySign() {
        char[] buffer = "-".toCharArray();
        NumberInput.parseBigDecimal(buffer, 0, 1);
    }
}
